// modelrumor.com renders its whole timeline server-side as one page, each
// entry a `.rumor-stop` element carrying data-model / data-date /
// data-released attributes — the same structured data their own published
// Skill (modelrumor.com/skills/show-next-week-model-rumors/SKILL.md) reads,
// so this is the one part of their markup they've committed to keeping
// stable. No LLM step needed here: unlike the news-feed source, this data
// arrives already extracted, just needs parsing and our own field names.
//
// aria-label is consistently `${provider} ${data-model}, ${their own
// confidence note}` — provider is recovered by finding where the known
// data-model text starts inside it, not by guessing a word-count split.
const html = $json.data ?? $json.body ?? (typeof $json === 'string' ? $json : '');

const re = /aria-label="([^"]*)" data-model="([^"]*)" data-date="([^"]*)" data-released="([^"]*)"/g;
const rows = [];
let m;
while ((m = re.exec(html))) {
  const [, ariaLabel, dataModel, dataDate, released] = m;
  if (released !== 'false') continue; // only the unreleased tier — a
  // model this site says has already shipped isn't this pipeline's job.

  const idx = ariaLabel.indexOf(dataModel);
  if (idx <= 0) continue; // pattern didn't match what we expect; skip rather than guess
  const provider = ariaLabel.slice(0, idx).trim();
  const afterModel = ariaLabel.slice(idx + dataModel.length);
  const note = afterModel.replace(/^,\s*/, '').trim();

  const name = dataModel.trim();
  const slug = name
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '');

  if (!provider || !name || !slug) continue;
  if (/^(unknown|n\/?a|none|tbd|<.*>)$/i.test(provider)) continue;
  if (!/^\d{4}-\d{2}-\d{2}$/.test(dataDate)) continue;

  rows.push({
    name,
    slug,
    provider,
    predictedDate: dataDate,
    summary: `Tracked by modelrumor.com${note ? ` (${note})` : ''}.`,
    sourceUrl: 'https://modelrumor.com',
  });
}

// De-dupe by slug — the page can list the same model more than once at
// different scroll positions in its rendered timeline.
const seen = new Set();
const rumors = rows.filter((r) => (seen.has(r.slug) ? false : (seen.add(r.slug), true)));

if (!rumors.length) return [];
return [{ json: { rumors } }];
